     7→// ===== Metrics Data Structures =====
     8→
     9→struct ExecutionRecord {
    10→    record_id: i32,
    11→    user_intent: String,
    12→    success: bool,
    13→    patches_applied: i32,
    14→    healing_success_rate: f32,
    15→    learning_rate: f32,
    16→    execution_time_ms: i32,
    17→    timestamp: String
    18→}
    19→
    20→trait ExecutionRecordCl {
    21→    fn clone(&self) -> ExecutionRecord;
    22→}
    23→
    24→impl ExecutionRecordCl for ExecutionRecord {
    25→    fn clone(&self) -> ExecutionRecord {
    26→        ExecutionRecord {
    27→            record_id: self.record_id,
    28→            user_intent: self.user_intent.clone(),
    29→            success: self.success,
    30→            patches_applied: self.patches_applied,
    31→            healing_success_rate: self.healing_success_rate,
    32→            learning_rate: self.learning_rate,
    33→            execution_time_ms: self.execution_time_ms,
    34→            timestamp: self.timestamp.clone()
    35→        }
    36→    }
    37→}
    38→
    39→struct AggregatedMetrics {
    40→    total_executions: i32,
    41→    success_count: i32,
    42→    failure_count: i32,
    43→    avg_healing_rate: f32,
    44→    avg_learning_rate: f32,
    45→    avg_execution_time_ms: i32,
    46→    total_patches_applied: i32,
    47→    uptime_seconds: i32
    48→}
    49→
    50→trait AggregatedMetricsCl {
    51→    fn clone(&self) -> AggregatedMetrics;
    52→}
    53→
    54→impl AggregatedMetricsCl for AggregatedMetrics {
    55→    fn clone(&self) -> AggregatedMetrics {
    56→        AggregatedMetrics {
    57→            total_executions: self.total_executions,
    58→            success_count: self.success_count,
    59→            failure_count: self.failure_count,
    60→            avg_healing_rate: self.avg_healing_rate,
    61→            avg_learning_rate: self.avg_learning_rate,
    62→            avg_execution_time_ms: self.avg_execution_time_ms,
    63→            total_patches_applied: self.total_patches_applied,
    64→            uptime_seconds: self.uptime_seconds
    65→        }
    66→    }
    67→}
    68→
    69→struct MetricsStore {
    70→    records: Vec<ExecutionRecord>,
    71→    next_id: i32,
    72→    server_start_time: String
    73→}
    74→
    75→trait MetricsStoreCl {
    76→    fn clone(&self) -> MetricsStore;
    77→}
    78→
    79→impl MetricsStoreCl for MetricsStore {
    80→    fn clone(&self) -> MetricsStore {
    81→        let mut cloned_records = vec![];
    82→        for i in 0..self.records.len() {
    83→            cloned_records.push(self.records[i].clone());
    84→        }
    85→        MetricsStore {
    86→            records: cloned_records,
    87→            next_id: self.next_id,
    88→            server_start_time: self.server_start_time.clone()
    89→        }
    90→    }
    91→}
    92→
    93→// ===== Metrics Management =====
    94→
    95→fn create_metrics_store() -> MetricsStore {
    96→    MetricsStore {
    97→        records: vec![],
    98→        next_id: 1,
    99→        server_start_time: "2026-03-18T00:00:00Z".to_string()
   100→    }
   101→}
   102→
   103→fn add_execution_record(store: MetricsStore, result: PipelineResult) -> MetricsStore {
   104→    let mut new_records = vec![];
   105→    for i in 0..store.records.len() {
   106→        new_records.push(store.records[i].clone());
   107→    }
   108→
   109→    let record = ExecutionRecord {
   110→        record_id: store.next_id,
   111→        user_intent: result.user_intent.clone(),
   112→        success: result.success,
   113→        patches_applied: result.patches_applied,
   114→        healing_success_rate: result.healing_success_rate,
   115→        learning_rate: result.learning_rate,
   116→        execution_time_ms: result.execution_time_ms,
   117→        timestamp: "2026-03-18T12:00:00Z".to_string()
   118→    };
   119→
   120→    new_records.push(record);
   121→
   122→    MetricsStore {
   123→        records: new_records,
   124→        next_id: store.next_id + 1,
   125→        server_start_time: store.server_start_time.clone()
   126→    }
   127→}
   128→
   129→fn get_recent_records(store: MetricsStore, limit: i32) -> Vec<ExecutionRecord> {
   130→    let mut result = vec![];
   131→    let start = if store.records.len() > (limit as usize) {
   132→        store.records.len() - (limit as usize)
   133→    } else {
   134→        0
   135→    };
   136→
   137→    for i in start..store.records.len() {
   138→        result.push(store.records[i].clone());
   139→    }
   140→    result
   141→}
   142→
   143→fn calculate_aggregated_metrics(store: MetricsStore) -> AggregatedMetrics {
   144→    let total = store.records.len() as i32;
   145→    let mut success_count = 0i32;
   146→    let mut healing_sum = 0.0f32;
   147→    let mut learning_sum = 0.0f32;
   148→    let mut time_sum = 0i32;
   149→    let mut patch_sum = 0i32;
   150→
   151→    for i in 0..store.records.len() {
   152→        if store.records[i].success {
   153→            success_count = success_count + 1;
   154→        }
   155→        healing_sum = healing_sum + store.records[i].healing_success_rate;
   156→        learning_sum = learning_sum + store.records[i].learning_rate;
   157→        time_sum = time_sum + store.records[i].execution_time_ms;
   158→        patch_sum = patch_sum + store.records[i].patches_applied;
   159→    }
   160→
   161→    let avg_healing = if total > 0 { healing_sum / (total as f32) } else { 0.0f32 };
   162→    let avg_learning = if total > 0 { learning_sum / (total as f32) } else { 0.0f32 };
   163→    let avg_time = if total > 0 { time_sum / total } else { 0i32 };
   164→
   165→    AggregatedMetrics {
   166→        total_executions: total,
   167→        success_count: success_count,
   168→        failure_count: total - success_count,
   169→        avg_healing_rate: avg_healing,
   170→        avg_learning_rate: avg_learning,
   171→        avg_execution_time_ms: avg_time,
   172→        total_patches_applied: patch_sum,
   173→        uptime_seconds: 3600i32
   174→    }
   175→}
   176→
   177→// ===== JSON Serialization =====
   178→
   179→fn pipeline_result_to_json(result: PipelineResult) -> String {
   180→    let mut json = String::new();
   181→    json.push_str("{");
   182→    json.push_str("\"success\":");
   183→    json.push_str(if result.success { "true" } else { "false" });
   184→    json.push_str(",\"user_intent\":\"");
   185→    json.push_str(result.user_intent.as_str());
   186→    json.push_str("\",\"patches_applied\":");
   187→    json.push_str(&result.patches_applied.to_string());
   188→    json.push_str(",\"healing_success_rate\":");
   189→    json.push_str(&result.healing_success_rate.to_string());
   190→    json.push_str(",\"learning_rate\":");
   191→    json.push_str(&result.learning_rate.to_string());
   192→    json.push_str(",\"execution_time_ms\":");
   193→    json.push_str(&result.execution_time_ms.to_string());
   194→    json.push_str("}");
   195→    json
   196→}
   197→
   198→fn aggregated_metrics_to_json(metrics: AggregatedMetrics) -> String {
   199→    let mut json = String::new();
   200→    json.push_str("{");
   201→    json.push_str("\"total_executions\":");
   202→    json.push_str(&metrics.total_executions.to_string());
   203→    json.push_str(",\"success_count\":");
   204→    json.push_str(&metrics.success_count.to_string());
   205→    json.push_str(",\"failure_count\":");
   206→    json.push_str(&metrics.failure_count.to_string());
   207→    json.push_str(",\"avg_healing_rate\":");
   208→    json.push_str(&metrics.avg_healing_rate.to_string());
   209→    json.push_str(",\"avg_learning_rate\":");
   210→    json.push_str(&metrics.avg_learning_rate.to_string());
   211→    json.push_str(",\"avg_execution_time_ms\":");
   212→    json.push_str(&metrics.avg_execution_time_ms.to_string());
   213→    json.push_str(",\"total_patches_applied\":");
   214→    json.push_str(&metrics.total_patches_applied.to_string());
   215→    json.push_str("}");
   216→    json
   217→}
   218→
   219→fn execution_record_to_json(record: ExecutionRecord) -> String {
   220→    let mut json = String::new();
   221→    json.push_str("{");
   222→    json.push_str("\"record_id\":");
   223→    json.push_str(&record.record_id.to_string());
   224→    json.push_str(",\"user_intent\":\"");
   225→    json.push_str(record.user_intent.as_str());
   226→    json.push_str("\",\"success\":");
   227→    json.push_str(if record.success { "true" } else { "false" });
   228→    json.push_str(",\"patches_applied\":");
   229→    json.push_str(&record.patches_applied.to_string());
   230→    json.push_str(",\"healing_success_rate\":");
   231→    json.push_str(&record.healing_success_rate.to_string());
   232→    json.push_str(",\"execution_time_ms\":");
   233→    json.push_str(&record.execution_time_ms.to_string());
   234→    json.push_str(",\"timestamp\":\"");
   235→    json.push_str(record.timestamp.as_str());
   236→    json.push_str("\"}");
   237→    json
   238→}
   239→
   240→fn history_to_json(records: Vec<ExecutionRecord>) -> String {
   241→    let mut json = String::new();
   242→    json.push_str("[");
   243→
   244→    for i in 0..records.len() {
   245→        json.push_str(execution_record_to_json(records[i].clone()).as_str());
   246→        if i < records.len() - 1 {
   247→            json.push_str(",");
   248→        }
   249→    }
   250→
   251→    json.push_str("]");
   252→    json
   253→}
   254→
   255→fn complex_scenario_to_json(scenario: ComplexScenario) -> String {
   256→    let mut json = String::new();
   257→    json.push_str("{");
   258→    json.push_str("\"scenario_id\":\"");
   259→    json.push_str(scenario.scenario_id.as_str());
   260→    json.push_str("\",\"total_success_rate\":");
   261→    json.push_str(&scenario.total_success_rate.to_string());
   262→    json.push_str(",\"total_learning_rate\":");
   263→    json.push_str(&scenario.total_learning_rate.to_string());
   264→    json.push_str(",\"execution_results_count\":");
   265→    json.push_str(&(scenario.execution_results.len() as i32).to_string());
   266→    json.push_str("}");
   267→    json
   268→}
   269→
   270→// ===== Public API =====
   271→
   272→fn create_metrics_api() -> MetricsStore {
   273→    create_metrics_store()
   274→}
   275→
   276→fn record_pipeline_execution(store: MetricsStore, result: PipelineResult) -> MetricsStore {
   277→    add_execution_record(store, result)
   278→}
   279→
   280→fn get_metrics_json(store: MetricsStore) -> String {
   281→    let metrics = calculate_aggregated_metrics(store);
   282→    aggregated_metrics_to_json(metrics)
   283→}
   284→
   285→fn get_history_json(store: MetricsStore, limit: i32) -> String {
   286→    let recent = get_recent_records(store, limit);
   287→    history_to_json(recent)
   288→}
   289→
   290→fn get_success_rate(store: MetricsStore) -> f32 {
   291→    if store.records.len() == 0 {
   292→        0.0f32
   293→    } else {
   294→        let mut success_count = 0i32;
   295→        for i in 0..store.records.len() {
   296→            if store.records[i].success {
   297→                success_count = success_count + 1;
   298→            }
   299→        }
   300→        (success_count as f32) / (store.records.len() as f32)
   301→    }
   302→}
