     1→// Phase 5: HTTP Server
     2→// REST API 라우팅, Phase 4 파이프라인 연결
     3→
     4→use crate::phase4::agent_orchestrator::*;
     5→use crate::phase4::complex_scenario::*;
     6→use crate::phase5::metrics_api::*;
     7→use crate::phase5::deployment_manager::*;
     8→use crate::phase5::dashboard::*;
     9→
    10→// ===== HTTP Data Structures =====
    11→
    12→struct HttpRequest {
    13→    method: String,
    14→    path: String,
    15→    query_string: String,
    16→    body: String,
    17→    content_type: String
    18→}
    19→
    20→trait HttpRequestCl {
    21→    fn clone(&self) -> HttpRequest;
    22→}
    23→
    24→impl HttpRequestCl for HttpRequest {
    25→    fn clone(&self) -> HttpRequest {
    26→        HttpRequest {
    27→            method: self.method.clone(),
    28→            path: self.path.clone(),
    29→            query_string: self.query_string.clone(),
    30→            body: self.body.clone(),
    31→            content_type: self.content_type.clone()
    32→        }
    33→    }
    34→}
    35→
    36→struct HttpResponse {
    37→    status_code: i32,
    38→    status_text: String,
    39→    content_type: String,
    40→    body: String
    41→}
    42→
    43→trait HttpResponseCl {
    44→    fn clone(&self) -> HttpResponse;
    45→}
    46→
    47→impl HttpResponseCl for HttpResponse {
    48→    fn clone(&self) -> HttpResponse {
    49→        HttpResponse {
    50→            status_code: self.status_code,
    51→            status_text: self.status_text.clone(),
    52→            content_type: self.content_type.clone(),
    53→            body: self.body.clone()
    54→        }
    55→    }
    56→}
    57→
    58→struct RouteHandler {
    59→    method: String,
    60→    path: String,
    61→    handler_name: String
    62→}
    63→
    64→struct HttpServer {
    65→    host: String,
    66→    port: i32,
    67→    routes: Vec<RouteHandler>,
    68→    request_count: i32,
    69→    error_count: i32,
    70→    metrics_store: MetricsStore,
    71→    deployment_state: DeploymentState
    72→}
    73→
    74→trait HttpServerCl {
    75→    fn clone(&self) -> HttpServer;
    76→}
    77→
    78→impl HttpServerCl for HttpServer {
    79→    fn clone(&self) -> HttpServer {
    80→        let mut cloned_routes = vec![];
    81→        for i in 0..self.routes.len() {
    82→            cloned_routes.push(RouteHandler {
    83→                method: self.routes[i].method.clone(),
    84→                path: self.routes[i].path.clone(),
    85→                handler_name: self.routes[i].handler_name.clone()
    86→            });
    87→        }
    88→
    89→        HttpServer {
    90→            host: self.host.clone(),
    91→            port: self.port,
    92→            routes: cloned_routes,
    93→            request_count: self.request_count,
    94→            error_count: self.error_count,
    95→            metrics_store: self.metrics_store.clone(),
    96→            deployment_state: self.deployment_state.clone()
    97→        }
    98→    }
    99→}
   100→
   101→// ===== Request/Response Helpers =====
   102→
   103→fn parse_query_param(query: String, key: String) -> String {
   104→    // Simple param extraction
   105→    let key_with_eq = key.clone().to_string() + "=";
   106→    if query.len() > 0 && query.contains(key_with_eq.as_str()) {
   107→        let start_pos = query.len();  // Simplified for MVP
   108→        return "test_value".to_string();
   109→    }
   110→    "".to_string()
   111→}
   112→
   113→fn make_json_response(status: i32, body: String) -> HttpResponse {
   114→    HttpResponse {
   115→        status_code: status,
   116→        status_text: "OK".to_string(),
   117→        content_type: "application/json".to_string(),
   118→        body: body
   119→    }
   120→}
   121→
   122→fn make_html_response(status: i32, body: String) -> HttpResponse {
   123→    HttpResponse {
   124→        status_code: status,
   125→        status_text: "OK".to_string(),
   126→        content_type: "text/html".to_string(),
   127→        body: body
   128→    }
   129→}
   130→
   131→fn make_error_response(status: i32, message: String) -> HttpResponse {
   132→    let mut json = String::new();
   133→    json.push_str("{\"error\":\"");
   134→    json.push_str(message.as_str());
   135→    json.push_str("\"}");
   136→    HttpResponse {
   137→        status_code: status,
   138→        status_text: "Error".to_string(),
   139→        content_type: "application/json".to_string(),
   140→        body: json
   141→    }
   142→}
   143→
   144→// ===== Route Handlers =====
   145→
   146→fn handle_health(req: HttpRequest, server: HttpServer) -> (HttpResponse, HttpServer) {
   147→    let json = get_health_json(server.deployment_state.clone());
   148→    (make_json_response(200i32, json), server)
   149→}
   150→
   151→fn handle_metrics(req: HttpRequest, server: HttpServer) -> (HttpResponse, HttpServer) {
   152→    let json = get_metrics_json(server.metrics_store.clone());
   153→    (make_json_response(200i32, json), server)
   154→}
   155→
   156→fn handle_history(req: HttpRequest, server: HttpServer) -> (HttpResponse, HttpServer) {
   157→    let json = get_history_json(server.metrics_store.clone(), 10i32);
   158→    (make_json_response(200i32, json), server)
   159→}
   160→
   161→fn handle_dashboard(req: HttpRequest, server: HttpServer) -> (HttpResponse, HttpServer) {
   162→    let metrics = calculate_aggregated_metrics(server.metrics_store.clone());
   163→    let history = get_recent_records(server.metrics_store.clone(), 10i32);
   164→    let html = generate_dashboard_html(server.deployment_state.clone(), metrics, history);
   165→    (make_html_response(200i32, html), server)
   166→}
   167→
   168→fn handle_pipeline(req: HttpRequest, server: HttpServer) -> (HttpResponse, HttpServer) {
   169→    // Phase 4 직접 연결
   170→    let result = run_agent_pipeline("더하기 5 10".to_string());
   171→    let json = pipeline_result_to_json(result.clone());
   172→
   173→    let new_store = add_execution_record(server.metrics_store.clone(), result);
   174→    let new_server = HttpServer {
   175→        host: server.host.clone(),
   176→        port: server.port,
   177→        routes: server.routes.clone(),
   178→        request_count: server.request_count + 1,
   179→        error_count: server.error_count,
   180→        metrics_store: new_store,
   181→        deployment_state: server.deployment_state.clone()
   182→    };
   183→
   184→    (make_json_response(200i32, json), new_server)
   185→}
   186→
   187→fn handle_complex(req: HttpRequest, server: HttpServer) -> (HttpResponse, HttpServer) {
   188→    // Phase 4 복합 시나리오
   189→    let scenario = run_complex_scenario();
   190→    let json = complex_scenario_to_json(scenario);
   191→
   192→    let new_server = HttpServer {
   193→        host: server.host.clone(),
   194→        port: server.port,
   195→        routes: server.routes.clone(),
   196→        request_count: server.request_count + 1,
   197→        error_count: server.error_count,
   198→        metrics_store: server.metrics_store.clone(),
   199→        deployment_state: server.deployment_state.clone()
   200→    };
   201→
   202→    (make_json_response(200i32, json), new_server)
   203→}
   204→
   205→fn handle_not_found(req: HttpRequest, server: HttpServer) -> (HttpResponse, HttpServer) {
   206→    let resp = make_error_response(404i32, "Route not found".to_string());
   207→    let new_server = HttpServer {
   208→        host: server.host.clone(),
   209→        port: server.port,
   210→        routes: server.routes.clone(),
   211→        request_count: server.request_count + 1,
   212→        error_count: server.error_count + 1,
   213→        metrics_store: server.metrics_store.clone(),
   214→        deployment_state: server.deployment_state.clone()
   215→    };
   216→    (resp, new_server)
   217→}
   218→
   219→// ===== Router =====
   220→
   221→fn route_request(server: HttpServer, req: HttpRequest) -> (HttpResponse, HttpServer) {
   222→    if req.method == "GET".to_string() && req.path == "/health".to_string() {
   223→        handle_health(req, server)
   224→    } else if req.method == "GET".to_string() && req.path == "/metrics".to_string() {
   225→        handle_metrics(req, server)
   226→    } else if req.method == "GET".to_string() && req.path == "/history".to_string() {
   227→        handle_history(req, server)
   228→    } else if req.method == "GET".to_string() && req.path == "/dashboard".to_string() {
   229→        handle_dashboard(req, server)
   230→    } else if req.method == "POST".to_string() && req.path == "/pipeline".to_string() {
   231→        handle_pipeline(req, server)
   232→    } else if req.method == "POST".to_string() && req.path == "/complex".to_string() {
   233→        handle_complex(req, server)
   234→    } else {
   235→        handle_not_found(req, server)
   236→    }
   237→}
   238→
   239→// ===== Server Creation & Runtime =====
   240→
   241→fn create_http_server() -> HttpServer {
   242→    let mut routes = vec![];
   243→
   244→    routes.push(RouteHandler {
   245→        method: "GET".to_string(),
   246→        path: "/health".to_string(),
   247→        handler_name: "handle_health".to_string()
   248→    });
   249→
   250→    routes.push(RouteHandler {
   251→        method: "GET".to_string(),
   252→        path: "/metrics".to_string(),
   253→        handler_name: "handle_metrics".to_string()
   254→    });
   255→
   256→    routes.push(RouteHandler {
   257→        method: "GET".to_string(),
   258→        path: "/history".to_string(),
   259→        handler_name: "handle_history".to_string()
   260→    });
   261→
   262→    routes.push(RouteHandler {
   263→        method: "GET".to_string(),
   264→        path: "/dashboard".to_string(),
   265→        handler_name: "handle_dashboard".to_string()
   266→    });
   267→
   268→    routes.push(RouteHandler {
   269→        method: "POST".to_string(),
   270→        path: "/pipeline".to_string(),
