   193→
   194→    for _i in 0..filled {
   195→        bar.push_str("█");
   196→    }
   197→    for _i in 0..empty {
   198→        bar.push_str("░");
   199→    }
   200→
   201→    bar.push_str("] ");
   202→    bar.push_str(&value.to_string());
   203→    bar.push_str("%\n");
   204→    bar
