   140→fn update_agent_status(state: DeploymentState, agent_name: String, success: bool) -> DeploymentState {
   141→    let mut updated_agents = vec![];
   142→
   143→    for i in 0..state.agent_statuses.len() {
   144→        let agent = &state.agent_statuses[i];
   145→        if agent.agent_name == agent_name {
   146→            let total = agent.total_executions + 1;
   147→            let success_count = if success {
   148→                (agent.success_rate * (agent.total_executions as f32)) as i32 + 1
   149→            } else {
   150→                (agent.success_rate * (agent.total_executions as f32)) as i32
   151→            };
   152→            let new_rate = (success_count as f32) / (total as f32);
   153→
   154→            updated_agents.push(AgentStatus {
   155→                agent_name: agent.agent_name.clone(),
   156→                status: "ACTIVE".to_string(),
   157→                last_execution: "2026-03-18T12:00:00Z".to_string(),
   158→                success_rate: new_rate,
   159→                total_executions: total
   160→            });
   161→        } else {
   162→            updated_agents.push(agent.clone());
   163→        }
   164→    }
   165→
   166→    DeploymentState {
   167→        service_info: state.service_info.clone(),
   168→        agent_statuses: updated_agents,
   169→        is_healthy: state.is_healthy,
   170→        pipeline_health: state.pipeline_health,
   171→        total_pipeline_runs: state.total_pipeline_runs
   172→    }
   173→}
