   185→fn refresh_pipeline_health(state: DeploymentState) -> DeploymentState {
   186→    let mut total_rate = 0.0f32;
   187→    for i in 0..state.agent_statuses.len() {
   188→        total_rate = total_rate + state.agent_statuses[i].success_rate;
   189→    }
   190→    let avg_health = total_rate / (state.agent_statuses.len() as f32);
   191→
   192→    DeploymentState {
   193→        service_info: state.service_info.clone(),
   194→        agent_statuses: state.agent_statuses.clone(),
   195→        is_healthy: avg_health > 0.9f32,
   196→        pipeline_health: avg_health,
   197→        total_pipeline_runs: state.total_pipeline_runs
   198→    }
   199→}
